def main():
    n, q = map(int, input().split())

    positions = [(i, 0) for i in range(1, n+1)]
    direction_map = {"R": (1, 0), "L": (-1, 0), "U": (0, 1), "D": (0, -1)}

    for _ in range(q):
        select, part = input().split()
        if select == "1":
            dx, dy = direction_map[part]
            new_head = (positions[0][0] + dx, positions[0][1] + dy)
            positions = [new_head] + positions[:-1]
        else:
            part = int(part)
            print(*positions[part-1])
